// setBodyState puzzle
function setBodyState(newState, objSelector) {
    if (!window.Ammo || !_pGlob.world)
        return;

    var objNames = PzLib.retrieveObjectNames(objSelector);

    objNames.forEach(function(objName) {
        if (!objName)
            return;

        var obj = PzLib.getObjectByName(objName);
        if (!obj)
            return;

        for (var i = 0; i < _pGlob.syncList.length; i++) {
            var syncData = _pGlob.syncList[i];

            if (syncData.obj == obj) {

                var body = syncData.body;

                switch (newState) {
                case 'ACTIVATE':
                    body.activate();
                    break;
                case 'SLEEP':
                    body.setActivationState(ISLAND_SLEEPING);
                    break;
                case 'ENABLE_SIMULATION':
                    body.setCollisionFlags(body.getCollisionFlags() & ~CF_NO_CONTACT_RESPONSE);
                    body.forceActivationState(ACTIVE_TAG);
                    body.activate();

                    PzLib.setPhysicsBodyTransformFromObj(body, syncData.obj);

                    syncData.simulated = true;
                    break;
                case 'DISABLE_SIMULATION':
                    body.setCollisionFlags(body.getCollisionFlags() | CF_NO_CONTACT_RESPONSE);
                    body.forceActivationState(DISABLE_SIMULATION);
                    syncData.simulated = false;
                    break;
                case 'RESET':
                    PzLib.resetPhysicsBody(body);
                    break;
                case 'ENABLE_CONTACT_RESP':
                    body.setCollisionFlags(body.getCollisionFlags() & ~CF_NO_CONTACT_RESPONSE);
                    break;
                case 'DISABLE_CONTACT_RESP':
                    body.setCollisionFlags(body.getCollisionFlags() | CF_NO_CONTACT_RESPONSE);
                    break;
                case 'MAKE_DYNAMIC':
                    body.setCollisionFlags(body.getCollisionFlags() & ~CF_KINEMATIC_OBJECT);
                    body.setCollisionFlags(body.getCollisionFlags() & ~CF_STATIC_OBJECT);

                    var localInertia = new Ammo.btVector3(0, 0, 0);
                    body.getCollisionShape().calculateLocalInertia(syncData.mass, localInertia);
                    body.setMassProps(syncData.mass, localInertia);

                    // enable deactivation
                    body.forceActivationState(ACTIVE_TAG);
                    body.activate();

                    break;
                case 'MAKE_KINEMATIC':
                    body.setCollisionFlags(body.getCollisionFlags() | CF_KINEMATIC_OBJECT);
                    body.setActivationState(DISABLE_DEACTIVATION);
                    break;
                case 'MAKE_STATIC':
                    body.setCollisionFlags(body.getCollisionFlags() | CF_STATIC_OBJECT);
                    break;
                case 'ENABLE_DEACTIVATION':
                    body.forceActivationState(ACTIVE_TAG);
                    break;
                case 'DISABLE_DEACTIVATION':
                    body.setActivationState(DISABLE_DEACTIVATION);
                    break;
                }

                // add / remove

            }

        }

    });
}

// dictSet puzzle
function dictSet(dict, key, value) {
    if (dict && typeof dict == 'object')
        dict[key] = value;
}

// dictGet puzzle
function dictGet(dict, key, defaultValue) {
    if (dict && typeof dict == 'object')
        return (key in dict) ? dict[key] : defaultValue;
}

// setMaterialValue puzzle
function setMaterialValue(matName, valName, value) {

    var values = PzLib.getMaterialEditableValues(matName);
    if (values.indexOf(valName) < 0)
        return;

    var mats = v3d.SceneUtils.getMaterialsByName(appInstance, matName);

    for (var i = 0; i < mats.length; i++) {
        var mat = mats[i];

        if (mat.isMeshNodeMaterial) {
            var valIdx = mat.nodeValueMap[valName];
            mat.nodeValue[valIdx] = Number(value);
        } else
            mat[valName] = Number(value);

        if (appInstance.scene !== null) {
            if (mat === appInstance.scene.worldMaterial) {
                appInstance.updateEnvironment(mat);
            }
        }
    }
}

