// animateParam puzzle
_pGlob.animateParamUpdate = 0;
_pGlob.animateParamTweenInstance = {};

function animateParam(from, to, duration, easing, easing2, repeat, yoyo, blockId, on_update, when_finished) {

    var mode = easing == "Linear" ?
        PzLib.Tween.Easing.Linear.None : PzLib.Tween.Easing[easing][easing2];

    var tweenObject = (typeof from != "number");

    if (!tweenObject) { // number
        from = [from];
        to = [to];
    }

    const tween = new PzLib.Tween.Tween(from)
                    .to(to, duration * 1000)
                    .easing(mode)
                    .repeat(repeat)
                    .yoyo(yoyo)
                    .onUpdate(function (object) {
                        if (tweenObject)
                            _pGlob.animateParamUpdate = object;
                        else // number
                            _pGlob.animateParamUpdate = object[0];
                        on_update();
                    })
                    .onComplete(function (object) {
                        when_finished();
                    })
                    .start();

    _pGlob.animateParamTweenInstance[blockId] = tween;
}

// detectCollision puzzle
function detectCollision(objSelectorA, objSelectorB, collideCb, noCollideCb) {
    if (!window.Ammo || !_pGlob.world)
        return;

    var objNamesA = PzLib.retrieveObjectNames(objSelectorA);
    var objNamesB = PzLib.retrieveObjectNames(objSelectorB);

    var objA = PzLib.getObjectByName(objNamesA[0]);
    var execInstanceID = v3d.MathUtils.generateUUID();

    for (var i = 0; i < objNamesB.length; i++) {
        var objB = PzLib.getObjectByName(objNamesB[i]);

        var bodyA = null;
        var bodyB = null;

        for (var j = 0; j < _pGlob.syncList.length; j++) {
            var syncData = _pGlob.syncList[j];

            if (syncData.obj == objA)
                bodyA = syncData.body;

            if (syncData.obj == objB)
                bodyB = syncData.body;
        }

        if (objA && objB && bodyA && bodyB) {
            _pGlob.collisionData.push({
                objA: objA,
                objB: objB,
                bodyA: bodyA,
                bodyB: bodyB,
                collideCb: collideCb,
                noCollideCb: noCollideCb,
                collideFlag: true,
                execInstanceID: execInstanceID
            });
        }
    }

}

