// createSoftBody puzzle
function createSoftBody(objSelector, shape, mass, pressure) {

    if (!window.Ammo || !_pGlob.world)
        return;

    if (!_pGlob.softBodyHelpers) {
        console.error('create soft body puzzle: Please activate soft body on the physics world');
        return;
    }

    var objNames = PzLib.retrieveObjectNames(objSelector);

    function processGeometry(bufGeometry) {

        // only consider the position values when merging the vertices
        var posOnlyBufGeometry = new v3d.BufferGeometry();
        posOnlyBufGeometry.setAttribute('position', bufGeometry.getAttribute('position'));
        posOnlyBufGeometry.setIndex(bufGeometry.getIndex());

        // Merge the vertices so the triangle soup is converted to indexed triangles
        var indexedBufferGeom = v3d.BufferGeometryUtils.mergeVertices(posOnlyBufGeometry);

        // Create index arrays mapping the indexed vertices to bufGeometry vertices
        mapIndices(bufGeometry, indexedBufferGeom);

    }

    function isEqual(x1, y1, z1, x2, y2, z2) {

        //var delta = 0.000001;
        var delta = 0.001;
        return Math.abs(x2 - x1) < delta &&
        Math.abs(y2 - y1) < delta &&
        Math.abs(z2 - z1) < delta;

    }

    function mapIndices(bufGeometry, indexedBufferGeom) {

        // Creates ammoVertices, ammoIndices and ammoIndexAssociation in bufGeometry

        var vertices = bufGeometry.attributes.position.array;
        var idxVertices = indexedBufferGeom.attributes.position.array;
        var indices = indexedBufferGeom.index.array;

        var numIdxVertices = idxVertices.length / 3;
        var numVertices = vertices.length / 3;

        bufGeometry.ammoVertices = idxVertices;
        bufGeometry.ammoIndices = indices;
        bufGeometry.ammoIndexAssociation = [];

        for (var i = 0; i < numIdxVertices; i++) {

            var association = [];
            bufGeometry.ammoIndexAssociation.push(association);

            var i3 = i * 3;

            for (var j = 0; j < numVertices; j ++) {

                var j3 = j * 3;
                if (isEqual(idxVertices[i3], idxVertices[i3 + 1], idxVertices[i3 + 2],
                        vertices[j3], vertices[j3 + 1], vertices[j3 + 2])) {

                    association.push(j3);

                }

            }

        }

    }

    function transformAmmoVertices(ammoVertices, matrix) {
        for (let i = 0; i < ammoVertices.length; i+=3) {
            const vert = _pGlob.vec3Tmp.fromArray(ammoVertices, i);
            vert.applyMatrix4(matrix);
            vert.toArray(ammoVertices, i);
        }
    }

    objNames.forEach(function(objName) {
        if (!objName)
            return;

        var obj = PzLib.getObjectByName(objName);
        if (!obj)
            return;

        PzLib.findAndRemovePhysicsBody(obj);

        const bufferGeom = obj.geometry;

        if (shape == 'ROPE') {
            mapIndices(bufferGeom, obj.userData.originalLineGeom);

            bufferGeom.ammoNeedNormals = false;

            const ammoVertices = bufferGeom.ammoVertices;
            const ammoVerticesLen = ammoVertices.length / 3;

            var softBody = new Ammo.btSoftBody(_pGlob.world.getWorldInfo());

            for (let i = 0; i < ammoVerticesLen; i++) {
                softBody.appendNode(new Ammo.btVector3(ammoVertices[3*i], ammoVertices[3*i+1], ammoVertices[3*i+2]), 1.0);
            }

            for (let i = 1; i < ammoVerticesLen; i++) {
                softBody.appendLink(i-1, i, false);
            }

            var sbConfig = softBody.get_m_cfg();
            sbConfig.set_viterations(10);
            sbConfig.set_piterations(10);

        } else if (shape == 'PATCH') {
            processGeometry(bufferGeom);

            bufferGeom.ammoNeedNormals = true;

            const ammoVertices = bufferGeom.ammoVertices;

            var softBody = new Ammo.btSoftBody(_pGlob.world.getWorldInfo());

            for (var i = 0; i < ammoVertices.length / 3; i++) {
                softBody.appendNode(new Ammo.btVector3(ammoVertices[3*i], ammoVertices[3*i+1], ammoVertices[3*i+2]), 1.0);
            }

            const ammoIndices = bufferGeom.ammoIndices;

            for (let i = 0; i < ammoIndices.length; i+=3) {
                var ind0 = ammoIndices[i];
                var ind1 = ammoIndices[i+1];
                var ind2 = ammoIndices[i+2];

                softBody.appendLink(ind0, ind1, false);
                softBody.appendLink(ind0, ind2, false);
                softBody.appendLink(ind1, ind2, false);

                softBody.appendFace(ind0, ind1, ind2);
            }

            var sbConfig = softBody.get_m_cfg();
            sbConfig.set_viterations(10);
            sbConfig.set_piterations(10);

            // Soft-soft and soft-rigid collisions
            sbConfig.set_collisions(0x11);

        } else {
            processGeometry(bufferGeom);

            bufferGeom.ammoNeedNormals = true;

            var softBody = _pGlob.softBodyHelpers.CreateFromTriMesh(
                  _pGlob.world.getWorldInfo(),
                  bufferGeom.ammoVertices,
                  bufferGeom.ammoIndices,
                  bufferGeom.ammoIndices.length / 3,
                  true);

            var sbConfig = softBody.get_m_cfg();
            sbConfig.set_viterations(40);
            sbConfig.set_piterations(40);

            // Soft-soft and soft-rigid collisions
            sbConfig.set_collisions(0x11);

            // Friction
            sbConfig.set_kDF(0.1);

            // Damping
            sbConfig.set_kDP(0.01);

            // Pressure
            sbConfig.set_kPR(pressure);

            // Stiffness
            softBody.get_m_materials().at(0).set_m_kLST(0.9);
            softBody.get_m_materials().at(0).set_m_kAST(0.9);
        }

        softBody.setTotalMass(mass, false);

        var margin = 0.05;
        Ammo.castObject(softBody, Ammo.btCollisionObject).getCollisionShape().setMargin(margin);


        // apply and reset initial object transform

        var pos = obj.getWorldPosition(_pGlob.vec3Tmp);
        var quat = obj.getWorldQuaternion(_pGlob.quatTmp);

        _pGlob.transTmp.setIdentity();
        _pGlob.transTmp.setOrigin(new Ammo.btVector3(pos.x, pos.y, pos.z));
        _pGlob.transTmp.setRotation(new Ammo.btQuaternion(quat.x, quat.y, quat.z, quat.w));

        softBody.transform(_pGlob.transTmp);

        // initial world space positions of simulated geometry
        transformAmmoVertices(bufferGeom.ammoVertices, obj.matrixWorld);

        obj.position.set(0, 0, 0);
        obj.quaternion.set(0, 0, 0, 1);

        _pGlob.world.addSoftBody(softBody, 1, -1);

        _pGlob.syncList.push({
            obj: obj,
            body: softBody,
            type: 'SOFT_BODY',
            simulated: true,
            mass: mass
        });

        // external physics interface
        if (PL) {
            PL.physics.bodies[objName] = softBody;
        }

    });


}

// softBodyApplyParam puzzle
function softBodyApplyParam(type, objSelector, param) {
    if (!window.Ammo || !_pGlob.world)
        return;

    const objNames = PzLib.retrieveObjectNames(objSelector);

    let vec;

    if (Array.isArray(param)) {
        vec = _pGlob.vec3Tmp.fromArray(param);
        PzLib.transformCoordsSpace(vec, PzLib.getSceneCoordSystem(), 'Y_UP_RIGHT');
    }

    objNames.forEach(function(objName) {
        if (!objName)
            return;

        const obj = PzLib.getObjectByName(objName);
        if (!obj)
            return;

        let btVec;

        for (var i = 0; i < _pGlob.syncList.length; i++) {
            const syncData = _pGlob.syncList[i];

            if (syncData.obj == obj) {

                if (syncData.type !== 'SOFT_BODY') {
                    console.error('apply soft body param puzzle: Not a soft body');
                    continue;
                }

                const body = syncData.body;

                if (Array.isArray(param))
                    btVec = new Ammo.btVector3(vec.x, vec.y, vec.z);

                switch (type) {
                case 'ANCHOR_HARDNESS':
                    body.get_m_cfg().set_kAHR(v3d.MathUtils.clamp(param, 0.0, 1.0));
                    break;
                case 'ANGULAR_STIFFNESS':
                    body.get_m_materials().at(0).set_m_kAST(v3d.MathUtils.clamp(param, 0.0, 1.0));
                    break;
                case 'COLLISION_FLAGS':
                    body.get_m_cfg().set_collisions(~~param);
                    break;
                case 'DAMPING':
                    body.get_m_cfg().set_kDP(v3d.MathUtils.clamp(param, 0.0, 1.0));
                    break;
                case 'DRAG':
                    body.get_m_cfg().set_kDG(Math.max(param, 0.0));
                    break;
                case 'FRICTION':
                    body.get_m_cfg().set_kDF(v3d.MathUtils.clamp(param, 0.0, 1.0));
                    break;
                case 'LIFT':
                    body.get_m_cfg().set_kLF(Math.max(param, 0.0));
                    break;
                case 'LINEAR_STIFFNESS':
                    body.get_m_materials().at(0).set_m_kLST(v3d.MathUtils.clamp(param, 0.0, 1.0));
                    break;
                case 'P_ITERATIONS':
                    body.get_m_cfg().set_piterations(~~param);
                    break;
                case 'PRESSURE':
                    body.get_m_cfg().set_kPR(param); // [-∞, +∞]
                    break;
                case 'V_ITERATIONS':
                    body.get_m_cfg().set_viterations(~~param);
                    break;
                case 'WIND_VELOCITY':
                    body.setWindVelocity(btVec);
                    break;
                }

                if (btVec)
                    Ammo.destroy(btVec);
            }
        }
    });
}

// softBodyAnchor puzzle
function softBodyAnchor(objName, targetObjName, at) {
    if (!window.Ammo || !_pGlob.world)
        return;

    if (!objName || !targetObjName)
        return;

    var obj = PzLib.getObjectByName(objName);
    var targetObj = PzLib.getObjectByName(targetObjName);
    if (!obj || !targetObj)
        return;

    for (var i = 0; i < _pGlob.syncList.length; i++) {
        var syncData = _pGlob.syncList[i];

        if (syncData.obj == obj) {
            for (var j = 0; j < _pGlob.syncList.length; j++) {
                var syncDataTarget = _pGlob.syncList[j];

                if (syncDataTarget.obj == targetObj) {

                    // find soft body node closest to the given point
                    if (Array.isArray(at)) {

                        var at = _pGlob.vec3Tmp.fromArray(at);
                        at = PzLib.transformCoordsSpace(at,
                                PzLib.getSceneCoordSystem(), 'Y_UP_RIGHT');

                        var positions = obj.geometry.ammoVertices;
                        var closestDistSq = Infinity;
                        var nodeIndex = 0;

                        for (var k = 0; k < positions.length/3; k++) {

                            var p = _pGlob.vec3Tmp2.set(positions[3*k], positions[3*k+1], positions[3*k+2]);
                            var dist = p.distanceToSquared(at);

                            if (dist < closestDistSq) {
                                closestDistSq = dist;
                                nodeIndex = k;
                            }
                        }

                        at = nodeIndex;
                    }

                    syncData.body.appendAnchor(at, syncDataTarget.body, true, 1.0);

                }
            }
        }
    }
}

// getHTMLElemAttribute puzzle
function getHTMLElemAttribute(attr, id, isParent) {
    var elem = PzLib.getElement(id, isParent);
    return elem ? elem[attr]: '';
}

// everyFrame puzzle
function registerEveryFrame(callback) {
    if (typeof callback == 'function') {
        appInstance.renderCallbacks.push(callback);
        if (PL.editorRenderCallbacks)
            PL.editorRenderCallbacks.push([appInstance, callback]);
    }
}

// cloneObject puzzle
function cloneObject(objName, cloneMaterials, preserveGroups) {
    if (!objName)
        return;
    const obj = PzLib.getObjectByName(objName);
    if (!obj)
        return;

    const objNew = obj.clone(); // recursive
    objNew.name = PzLib.generateUniqueObjectName(obj.name);

    // assign unique names for multi-material object meshes
    const objsM = objNew.resolveMultiMaterial();
    if (objNew != objsM[0])
        for (let i = 0; i < objsM.length; i++)
            objsM[i].name = objNew.name + 'MatMesh' + i;

    if (cloneMaterials) {
        objNew.traverse(o => {
            if (o.material) {
                o.material = o.material.clone();
            }
        });
    }

    if (preserveGroups) {
        const oldGroups = [];
        obj.traverse(o => {
            oldGroups.push(o.groupNames);
        });

        let i = 0;
        objNew.traverse(o => {
            o.groupNames.push(...oldGroups[i]);
            i++;
        });
    }

    appInstance.scene.add(objNew);

    // add object to cache now to increase performance
    _pGlob.objCache.set(objNew.name, objNew);

    return objNew.name;
}

// snapBody puzzle
function snapBody(objName, targetObjName) {
    if (!window.Ammo || !_pGlob.world)
        return;

    if (!objName || !targetObjName)
        return;

    var obj = PzLib.getObjectByName(objName);
    var targetObj = PzLib.getObjectByName(targetObjName);
    if (!obj || !targetObj)
        return;

    for (var i = 0; i < _pGlob.syncList.length; i++) {
        var syncData = _pGlob.syncList[i];

        if (syncData.obj == obj) {

            // snap verge3d object itself
            obj.copyTransform(targetObj);

            PzLib.setPhysicsBodyTransformFromObj(syncData.body, obj);

        }
    }
}

// Describe this function...
function shoot() {
    shootDir = getObjDirection('respawn_axis', 'XYZ');
    clonedBall = cloneObject('Ball', false, false);
    createPhysicsBody('DYNAMIC', clonedBall, 'SPHERE', 0.3);
    physicsBodyApplyParam('LINEAR_DAMPING', clonedBall, 0.001);
    physicsBodyApplyParam('ANGULAR_DAMPING', clonedBall, 0.001);
    physicsBodyApplyParam('FRICTION', clonedBall, 0.1);
    setBodyState('DISABLE_DEACTIVATION', clonedBall);
    snapBody(clonedBall, 'respawn_axis');
    setVectorValue(shootDir, 'LENGTH', ballPower);
    physicsBodyApplyParam('IMPULSE', clonedBall, shootDir);
    physicsBodyApplyParam('RESTITUTION', clonedBall, 0.08);
    setHTMLElemStyle('left', '0px', 'shoot_button_ball', false);
    ballPower = 0;
    ballCharging = false;
    ballOnTable = true;
    death_zone_enable();
    speedup_1();
    speedup_box();
    lights();
}

// getEventProperty puzzle
function getEventProperty(prop, event) {
    if (typeof event != "undefined") {
        switch (prop) {
            case 'target.checked':
                return event.target.checked;
            case 'target.id':
                return event.target.id;
            case 'target.value':
                return event.target.value;
            case 'touches.length':
                return event.touches ? event.touches.length : 0;
            case 'touches[0].pageX':
                return event.touches[0].pageX;
            case 'touches[0].pageY':
                return event.touches[0].pageY;
            case 'touches[1].pageX':
                return event.touches[1].pageX;
            case 'touches[1].pageY':
                return event.touches[1].pageY;
            case 'targetTouches.length':
                return event.targetTouches ? event.targetTouches.length : 0;
            case 'targetTouches[0].pageX':
                return event.targetTouches[0].pageX;
            case 'targetTouches[0].pageY':
                return event.targetTouches[0].pageY;
            case 'targetTouches[1].pageX':
                return event.targetTouches[1].pageX;
            case 'targetTouches[1].pageY':
                return event.targetTouches[1].pageY;
            default:
                return event[prop];
        }
    }
}

// setObjTransform puzzle
function setObjTransform(objSelector, isWorldSpace, mode, vector, offset) {
    const x = vector[0];
    const y = vector[1];
    const z = vector[2];

    if (isNaN(x) || isNaN(y) || isNaN(z)) {
        console.error('set transform puzzle: Invalid transform');
        return;
    }

    const objNames = PzLib.retrieveObjectNames(objSelector);

    function setObjProp(obj, prop, val) {
        if (!offset) {
            obj[mode][prop] = val;
        } else {
            if (mode != "scale")
                obj[mode][prop] += val;
            else
                obj[mode][prop] *= val;
        }
    }

    const inputsUsed = _pGlob.vec3Tmp.set(Number(x !== ''), Number(y !== ''), Number(z !== ''));
    const coords = _pGlob.vec3Tmp2.set(x || 0, y || 0, z || 0);

    if (mode === 'rotation') {
        // rotations are specified in degrees
        coords.multiplyScalar(v3d.MathUtils.DEG2RAD);
    }

    const coordSystem = PzLib.getSceneCoordSystem();

    PzLib.transformCoordsSpace(inputsUsed, coordSystem, 'Y_UP_RIGHT', true);
    PzLib.transformCoordsSpace(coords, coordSystem, 'Y_UP_RIGHT', mode === 'scale');

    for (let i = 0; i < objNames.length; i++) {

        const objName = objNames[i];
        if (!objName) continue;

        const obj = PzLib.getObjectByName(objName);
        if (!obj) continue;

        if (isWorldSpace && obj.parent) {
            obj.matrixWorld.decomposeE(obj.position, obj.rotation, obj.scale);

            if (inputsUsed.x) setObjProp(obj, "x", coords.x);
            if (inputsUsed.y) setObjProp(obj, "y", coords.y);
            if (inputsUsed.z) setObjProp(obj, "z", coords.z);

            obj.matrixWorld.composeE(obj.position, obj.rotation, obj.scale);
            obj.matrix.multiplyMatrices(_pGlob.mat4Tmp.copy(obj.parent.matrixWorld).invert(), obj.matrixWorld);
            obj.matrix.decompose(obj.position, obj.quaternion, obj.scale);

        } else if (mode === 'rotation' && coordSystem == 'Z_UP_RIGHT') {
            // Blender/Max coordinates

            // need all the rotations for order conversions, especially if some
            // inputs are not specified
            const euler = PzLib.transformEulerV3dToBlenderShortest(obj.rotation,
                    _pGlob.eulerTmp);
            PzLib.transformCoordsSpace(euler, coordSystem, 'Y_UP_RIGHT');

            if (inputsUsed.x) euler.x = offset ? euler.x + coords.x : coords.x;
            if (inputsUsed.y) euler.y = offset ? euler.y + coords.y : coords.y;
            if (inputsUsed.z) euler.z = offset ? euler.z + coords.z : coords.z;

            /**
             * convert from Blender/Max default XYZ extrinsic order to v3d XYZ
             * intrinsic with reversion (XYZ -> ZYX) and axes swizzling (ZYX -> YZX)
             */
            euler.order = "YZX";
            euler.reorder(obj.rotation.order);
            obj.rotation.copy(euler);

        } else if (mode === 'rotation' && coordSystem == 'Y_UP_RIGHT') {
            // Maya coordinates

            // Use separate rotation interface to fix ambiguous rotations for Maya,
            // might as well do the same for Blender/Max.

            const rotUI = PzLib.RotationInterface.initObject(obj);
            const euler = rotUI.getUserRotation(_pGlob.eulerTmp);
            // TODO(ivan): this probably needs some reasonable wrapping
            if (inputsUsed.x) euler.x = offset ? euler.x + coords.x : coords.x;
            if (inputsUsed.y) euler.y = offset ? euler.y + coords.y : coords.y;
            if (inputsUsed.z) euler.z = offset ? euler.z + coords.z : coords.z;

            rotUI.setUserRotation(euler);
            rotUI.getActualRotation(obj.rotation);
        } else {
            if (inputsUsed.x) setObjProp(obj, "x", coords.x);
            if (inputsUsed.y) setObjProp(obj, "y", coords.y);
            if (inputsUsed.z) setObjProp(obj, "z", coords.z);
        }

        obj.updateWorldMatrix(false, true);
    }

}


