eventHTMLElem('keyup', ['WINDOW'], false, function(event) {
    if ('ArrowLeft' == getEventProperty('key', event)) {
        left_flipper_hold = false;
    }
    if ('ArrowRight' == getEventProperty('key', event)) {
        right_flipper_hold = false;
    }
});

registerEveryFrame(function() {
    if (left_flipper_hold) {
        if (left_flipper_rotation <= 40) {
            left_flipper_rotation = left_flipper_rotation + left_flipper_rotation_factor;
            left_flipper_rotation_factor = left_flipper_rotation_factor * 1.2;
        }
        setObjTransform('flipper_left', false, 'rotation', ['', '', left_flipper_rotation], false);
    } else {
        setObjTransform('flipper_left', false, 'rotation', ['', '', 0], false);
        left_flipper_rotation = 0;
        left_flipper_rotation_factor = 5;
    }
    if (right_flipper_hold) {
        if (right_flipper_rotation >= -40) {
            right_flipper_rotation = right_flipper_rotation - right_flipper_rotation_factor;
            right_flipper_rotation_factor = right_flipper_rotation_factor * 1.2;
        }
        setObjTransform('flipper_right', false, 'rotation', ['', '', right_flipper_rotation], false);
    } else {
        setObjTransform('flipper_right', false, 'rotation', ['', '', 0], false);
        right_flipper_rotation = 0;
        right_flipper_rotation_factor = 5;
    }
});

